"""Canonical persisted argument shapes for safe tool replay."""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass

from codey.runtime.effects.replay_policy import IDEMPOTENT_RUNTIME_TOOL_NAMES, is_replayable_safe_tool
from codey.toolchain.definition import TOOL_DEFINITION_BY_NAME
from codey.toolchain.tool_args_repair import ToolArgLimits, normalize_tool_args

REPLAY_ARG_TEXT_MAX_CHARS = 1000
REPLAY_READ_MAX_LINES = ToolArgLimits().read_max_lines
_REPLAY_READ_MAX_OFFSET = 1_000_000_000


@dataclass(frozen=True)
class ReplayArgSpec:
    allowed: frozenset[str]
    required: frozenset[str]


_REPLAY_ARG_SPECS = {
    "read": ReplayArgSpec(
        allowed=frozenset({"path", "offset", "limit"}),
        required=frozenset({"path"}),
    ),
    "ls": ReplayArgSpec(
        allowed=frozenset({"path"}),
        required=frozenset({"path"}),
    ),
    "search": ReplayArgSpec(
        allowed=frozenset(key for key, _schema in TOOL_DEFINITION_BY_NAME["grep"].parameters),
        required=frozenset({"path", "query"}),
    ),
    "references": ReplayArgSpec(
        allowed=frozenset({"path", "symbol"}),
        required=frozenset({"path", "symbol"}),
    ),
}
REPLAY_ARG_TOOL_NAMES = frozenset(_REPLAY_ARG_SPECS) | IDEMPOTENT_RUNTIME_TOOL_NAMES | {"codemode"}


def _validate_replay_text_arg(value: object, key: str) -> str:
    if not isinstance(value, str):
        raise ValueError(f"{key} must be a string")
    if not value.strip():
        raise ValueError(f"{key} cannot be empty")
    if len(value) > REPLAY_ARG_TEXT_MAX_CHARS:
        raise ValueError(f"{key} exceeds max length {REPLAY_ARG_TEXT_MAX_CHARS}")
    return value


def _validate_replay_path(value: object) -> str:
    path = _validate_replay_text_arg(value, "path")
    if path.strip() != path:
        raise ValueError("path must already be canonical")
    if "\\" in path or path.startswith("/") or path.startswith("//"):
        raise ValueError("path must be project-relative and canonical")
    if len(path) >= 2 and path[1] == ":" and path[0].isalpha():
        raise ValueError("path must be project-relative and canonical")
    if path != ".":
        parts = path.split("/")
        if any(part in {"", ".", ".."} for part in parts):
            raise ValueError("path must already be canonical")
    return path


def _validate_replay_positive_int(value: object, key: str, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{key} must be a positive integer")
    if value < 1:
        raise ValueError(f"{key} must be a positive integer")
    if value > maximum:
        raise ValueError(f"{key} exceeds max value {maximum}")
    return value


def _validate_knowledge_commit(args: Mapping[str, object]) -> dict[str, object]:
    import json

    if set(args) != {"commit_id", "changes"} or not isinstance(args["changes"], list):
        raise ValueError("knowledge replay requires its original commit_id and changes")
    _validate_replay_text_arg(args["commit_id"], "commit_id")
    if not 1 <= len(args["changes"]) <= 128:
        raise ValueError("knowledge replay batch is out of bounds")
    for row in args["changes"]:
        if (not isinstance(row, dict) or set(row) != {"value", "expected_revision"}
                or not isinstance(row["value"], dict)
                or type(row["expected_revision"]) is not int or row["expected_revision"] < 0):
            raise ValueError("invalid knowledge replay mutation")
    # Domain validation remains in the knowledge executor. Recovery preserves the
    # exact JSON payload; no alias repair, model call or speculative rewriting.
    json.dumps(dict(args), allow_nan=False)
    return dict(args)


def _validate_research_answer(args: Mapping[str, object]) -> dict[str, object]:
    import json

    state = args.get("state")
    if not isinstance(state, str) or state not in {"answered", "partial", "unresolved"}:
        raise ValueError("research answer replay requires its explicit original state")
    if set(args) in ({"state", "markdown"}, {"state", "markdown", "knowledge_updates"}):
        if not isinstance(args["markdown"], str) or not 12 <= len(args["markdown"].strip()) <= 64000:
            raise ValueError("invalid original whole-answer declaration")
        if "knowledge_updates" in args:
            from codey.research.knowledge_updates import MAX_UPDATES

            updates = args["knowledge_updates"]
            if not isinstance(updates, list) or len(updates) > MAX_UPDATES or any(not isinstance(row, dict) for row in updates):
                raise ValueError("invalid original whole-answer knowledge batch")
    elif set(args) == {"state", "findings"}:
        refs = args["findings"]
        if (not isinstance(refs, list) or len(refs) > 16 or any(not isinstance(ref, str) for ref in refs)
                or len(set(refs)) != len(refs) or bool(refs) != (state != "unresolved")):
            raise ValueError("invalid original research selection")
    elif set(args) == {"state", "finding"}:
        if state == "unresolved" or not isinstance(args["finding"], dict):
            raise ValueError("invalid original inline declaration")
    else:
        raise ValueError("research answer replay requires one original selection form")
    # Only preserve shape and exact JSON here. The original frozen contract,
    # scope, passages and knowledge executor validate meaning before any write.
    json.dumps(dict(args), allow_nan=False)
    return dict(args)


def _validate_revision_preparation(args: Mapping[str, object]) -> dict[str, object]:
    if args:
        raise ValueError("revision preparation takes no arguments")
    return {}


def validate_replay_args_shape(
    tool_name: str,
    args: object,
) -> dict[str, object]:
    """Validate persisted replay args without aliases, repairs, or defaults."""
    canonical_name = (tool_name or "").strip()
    if not is_replayable_safe_tool(canonical_name):
        raise ValueError(f"tool is not replayable: {canonical_name}")
    if not isinstance(args, Mapping):
        raise ValueError("replay args must be a mapping")
    validator = {"knowledge_commit": _validate_knowledge_commit, "submit_research_answer": _validate_research_answer,
                 "prepare_knowledge_revision": _validate_revision_preparation}.get(canonical_name)
    if validator is not None:
        return validator(args)
    if canonical_name == "submit_research_review":
        import json

        if (set(args) != {"basis_digest", "assessment"} or not isinstance(args["basis_digest"], str)
                or len(args["basis_digest"]) != 64 or not isinstance(args["assessment"], dict)):
            raise ValueError("review replay requires its original basis digest and assessment")
        json.dumps(dict(args), allow_nan=False)
        return dict(args)
    if canonical_name == "codemode":
        from codey.codemode.protocol import parse_codemode_args
        from codey.toolchain.tool_spec import spec_for_tool

        codemode_spec = spec_for_tool("codemode")
        if codemode_spec is None or set(args) - {key for key, _schema in codemode_spec.parameters}:
            raise ValueError("unsupported CodeMode replay arguments")
        parse_codemode_args(args)
        return dict(args)

    keys: set[str] = set()
    for key in args:
        if not isinstance(key, str) or not key:
            raise ValueError(f"invalid replay arg key: {key}")
        keys.add(key)

    spec = _REPLAY_ARG_SPECS.get(canonical_name)
    if spec is None:
        raise ValueError(f"tool has no replay arg schema: {canonical_name}")
    unknown = sorted(keys - spec.allowed)
    if unknown:
        raise ValueError(f"unsupported replay arg fields: {', '.join(unknown)}")
    missing = sorted(spec.required - keys)
    if missing:
        raise ValueError(f"missing replay arg fields: {', '.join(missing)}")

    validated: dict[str, object] = {"path": _validate_replay_path(args["path"])}
    if canonical_name == "read":
        if "offset" in args:
            validated["offset"] = _validate_replay_positive_int(
                args["offset"],
                "offset",
                _REPLAY_READ_MAX_OFFSET,
            )
        if "limit" in args:
            validated["limit"] = _validate_replay_positive_int(
                args["limit"],
                "limit",
                REPLAY_READ_MAX_LINES,
            )
    elif canonical_name == "search":
        validated["query"] = _validate_replay_text_arg(args["query"], "query")
        normalized = normalize_tool_args(canonical_name, args)
        if normalized.alias_rewrite_count or normalized.arg_repair_counts or normalized.args != dict(args):
            raise ValueError("search replay arguments must be strictly canonical")
        if "include" in args and len(str(args["include"])) > REPLAY_ARG_TEXT_MAX_CHARS:
            raise ValueError("search include exceeds replay text limit")
        validated.update(normalized.args)
    elif canonical_name == "references":
        validated["symbol"] = _validate_replay_text_arg(args["symbol"], "symbol")
    return validated


__all__ = [
    "REPLAY_ARG_TOOL_NAMES",
    "REPLAY_ARG_TEXT_MAX_CHARS",
    "REPLAY_READ_MAX_LINES",
    "validate_replay_args_shape",
]

source_snapshot.codey/runtime/effects/replay_policy.py:
"""Tool and runtime effect replay policy.

Classifies external effects into safe (pure information, idempotent projection)
and unsafe (filesystem edits, command execution, shell approval, provider calls,
repair rounds, and unknown tools).
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

from codey.toolchain.definition import (
    READ_ONLY_RUNTIME_TOOL_NAMES,
    SUPPORTED_RUNTIME_TOOL_NAMES,
)

SAFE_RUNTIME_TOOL_NAMES = READ_ONLY_RUNTIME_TOOL_NAMES
# The retired review name classifies archived intents only. This whitelist
# never grants current execution; admission still needs a live frozen tool.
IDEMPOTENT_RUNTIME_TOOL_NAMES = frozenset({
    "knowledge_commit", "submit_research_review", "submit_research_answer", "prepare_knowledge_revision",
})
UNSAFE_RUNTIME_TOOL_NAMES = SUPPORTED_RUNTIME_TOOL_NAMES - SAFE_RUNTIME_TOOL_NAMES
# CodeMode is a resumable container. Its recovery still re-enters the kernel;
# it is never passed to the information-tool dispatcher.
REPLAYABLE_SAFE_TOOL_NAMES = SAFE_RUNTIME_TOOL_NAMES | IDEMPOTENT_RUNTIME_TOOL_NAMES | {"codemode"}


def is_replayable_safe_tool(tool_name: str) -> bool:
    """Return True if tool_name is in the replayable safe tools whitelist."""
    return (tool_name or "").strip() in REPLAYABLE_SAFE_TOOL_NAMES


class ReplayClass:
    SAFE: Literal["safe"] = "safe"
    UNSAFE: Literal["unsafe"] = "unsafe"


ReplayClassType = Literal["safe", "unsafe"]


@dataclass(frozen=True)
class ReplayDecision:
    replay_class: ReplayClassType
    reason: str


def tool_replay_policy(
    tool_name: str,
    *,
    policy_denied: bool = False,
    approval_required: bool = False,
) -> ReplayDecision:
    """Classify a tool call into a safe or unsafe replay decision.

    'run' is unconditionally unsafe regardless of command string.
    Unknown tools default to unsafe fail-closed.
    """
    canonical_name = (tool_name or "").strip()
    if policy_denied:
        return ReplayDecision(
            replay_class=ReplayClass.UNSAFE,
            reason="policy_denied",
        )
    if approval_required or canonical_name == "shell":
        return ReplayDecision(
            replay_class=ReplayClass.UNSAFE,
            reason="approval_required" if approval_required else "shell_command",
        )
    if canonical_name in SAFE_RUNTIME_TOOL_NAMES:
        return ReplayDecision(
            replay_class=ReplayClass.SAFE,
            reason="read_only_tool",
        )
    if canonical_name in IDEMPOTENT_RUNTIME_TOOL_NAMES:
        reason = "idempotent_tool_preparation" if canonical_name == "prepare_knowledge_revision" else "idempotent_knowledge_transaction"
        return ReplayDecision(replay_class=ReplayClass.SAFE, reason=reason)
    if canonical_name in UNSAFE_RUNTIME_TOOL_NAMES:
        return ReplayDecision(
            replay_class=ReplayClass.UNSAFE,
            reason="mutating_or_executing_tool",
        )
    return ReplayDecision(
        replay_class=ReplayClass.UNSAFE,
        reason="unknown_tool",
    )


def provider_replay_policy() -> ReplayDecision:
    """Classify an outbound provider prompt send."""
    return ReplayDecision(
        replay_class=ReplayClass.UNSAFE,
        reason="outbound_provider_call",
    )


def repair_replay_policy() -> ReplayDecision:
    """Classify a bounded completion repair round."""
    return ReplayDecision(
        replay_class=ReplayClass.UNSAFE,
        reason="completion_repair_round",
    )


__all__ = [
    "REPLAYABLE_SAFE_TOOL_NAMES",
    "ReplayClass",
    "ReplayClassType",
    "ReplayDecision",
    "SAFE_RUNTIME_TOOL_NAMES",
    "UNSAFE_RUNTIME_TOOL_NAMES",
    "is_replayable_safe_tool",
    "provider_replay_policy",
    "repair_replay_policy",
    "tool_replay_policy",
]

source_snapshot.codey/toolchain/tool_spec.py:
"""One tool registry for the unified kernel (operations-facing).

Coding definitions, Research contracts, and controller aliases converge here
as ``ToolSpec`` rows: one grant, one parameter schema, one canonical name.
Text batch wrappers lower to validated project calls before execution. Native
calls use individual ids; wrappers are never advertised there. Unknown tools
are denied, never passed as ``control``.
"""

from __future__ import annotations

import json
from collections.abc import Mapping
from dataclasses import dataclass, field, replace
from types import MappingProxyType
from typing import Any, cast

from codey.toolchain.constants import ARGUMENT_CONTENT_GUIDANCE
from codey.toolchain.result_schema import text_output_schema
from codey.toolchain.tool_prompt import json_contract_text as json_contract_text
from codey.toolchain.tool_prompt import model_tool_description

_TEXT_BATCH_TOOLS = frozenset({"parallel", "read_files"})


def is_text_batch_tool(name: str) -> bool:
    """Wrappers need text-plan lowering; they are not callable tool leaves."""
    return name in _TEXT_BATCH_TOOLS

# Native (runtime) alias -> canonical model name for coding tools.
_NATIVE_TO_CANONICAL = {
    "ls": "list_dir",
    "read": "read_file",
    "search": "grep",
    "references": "find_references",
    "edit": "edit",
    "run": "run",
    "shell": "shell",
    "done": "done",
}

# Controller alias -> canonical research tool + required id arg.
_CONTROLLER_ALIAS_ID_ARG = {
    "open_result": ("open_url", "result_id"),
    "reopen_source": ("open_url", "source_id"),
    "open_hit": ("open_url", "hit_id"),
}


@dataclass(frozen=True)
class ToolSpec:
    name: str
    aliases: tuple[str, ...] = ()
    grant: str = ""
    parameters: tuple[tuple[str, object], ...] = ()
    required: tuple[str, ...] = ()
    json_examples: tuple[str, ...] = ()
    description: str = ""
    executor: str = ""
    replay_class: str = "unsafe"
    parallel_safe: bool = False
    output_schema: Mapping[str, object] = field(default_factory=text_output_schema)
    declarations: str = ""


def _freeze_schema_value(value: object) -> object:
    """Freeze every nested schema mapping and sequence."""
    if isinstance(value, Mapping):
        return MappingProxyType({key: _freeze_schema_value(item) for key, item in value.items()})
    if isinstance(value, (list, tuple)):
        return tuple(_freeze_schema_value(item) for item in value)
    return value


def thaw_schema_value(value: Any) -> Any:
    """Create an independent JSON-compatible transport value."""
    if isinstance(value, Mapping):
        return {key: thaw_schema_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [thaw_schema_value(item) for item in value]
    return value


def freeze_spec_parameters(spec: ToolSpec) -> ToolSpec:
    """Return a copy of ``spec`` with nested parameter schemas frozen."""
    from dataclasses import replace as _replace

    if not _valid_custom_schema(thaw_schema_value(spec.output_schema)):
        raise ValueError(f"invalid output schema for {spec.name}")
    try:
        params = tuple(
            (key, _freeze_schema_value(schema))
            for key, schema in (getattr(spec, "parameters", ()) or ())
        )
    except Exception as exc:
        raise RuntimeError(f"tool snapshot freeze failed for {getattr(spec, 'name', '?')}: {exc}") from exc
    return _replace(spec, parameters=params,
                    output_schema=cast(Mapping[str, object], _freeze_schema_value(spec.output_schema)))


def _coding_specs() -> dict[str, ToolSpec]:
    from codey.toolchain import definition as tool_defs

    specs: dict[str, ToolSpec] = {}
    grant_by_permission = {
        "project_read": "project.read",
        "project_write": "project.write",
        "project_verify": "project.verify",
        "user_approved_shell": "shell.approval",
        "control": "control",
    }
    for definition in tool_defs.TOOL_DEFINITIONS:
        grant = grant_by_permission.get(definition.permission, "")
        if not grant:
            continue
        specs[definition.name] = ToolSpec(
            name=definition.name,
            aliases=tuple(definition.aliases),
            grant=grant,
            parameters=tuple(definition.parameters),
            required=() if definition.name == "list_dir" else tuple(definition.required),
            json_examples=definition.examples,
            description=definition.description,
            executor="project",
            replay_class="safe" if definition.read_only else "unsafe",
            parallel_safe=definition.parallel_safe,
            output_schema=definition.output_schema,
        )
    return specs


def _research_specs() -> dict[str, ToolSpec]:
    from codey.research.tool_contract import TOOL_CONTRACTS

    grant_by_tool = {
        "research_plan": "knowledge.read",
        "web_search": "web.read",
        "open_url": "web.read",
        "source_search": "web.read",
        "knowledge_search": "knowledge.read",
        "knowledge_read": "knowledge.read",
        "knowledge_write": "knowledge.write",
        "save_finding": "knowledge.write",
        "save_inference": "knowledge.write",
        "knowledge_commit": "knowledge.write",
        "knowledge_link": "knowledge.link",
        "submit_research_answer": "knowledge.write",
        "done": "control",
    }
    specs: dict[str, ToolSpec] = {}
    for name, grant in grant_by_tool.items():
        contract = TOOL_CONTRACTS.get(name)
        if contract is None:
            continue
        specs[name] = ToolSpec(
            name=name,
            aliases=(),
            grant=grant,
            parameters=tuple(contract.input_schema["properties"].items()),
            required=tuple(contract.input_schema["required"]),
            json_examples=(contract.example,),
            description=contract.description,
            executor="source" if grant == "web.read" else "knowledge",
            replay_class="safe" if grant in {"web.read", "knowledge.read"} or name in {"knowledge_commit", "save_finding", "save_inference", "submit_research_answer"} else "unsafe",
            parallel_safe=contract.parallel_safe,
        )
    for alias, (_canonical, id_arg) in _CONTROLLER_ALIAS_ID_ARG.items():
        reference_help = {
            "open_result": "Open a web_search hit. result_id is r1, r2, etc. from Search result references; "
                           "never pass a tool result_ref or URL. For a URL use open_url(url).",
            "reopen_source": "Read an opened source again. source_id is s1, s2, etc. from Opened source references.",
            "open_hit": "Read a located passage. hit_id is the exact id returned by source_search.",
        }
        specs[alias] = ToolSpec(
            name=alias,
            aliases=(),
            grant="web.read",
            parameters=((id_arg, {"type": "string"}),),
            required=(id_arg,),
            json_examples=(f'{{"tool":"{alias}","args":{{"{id_arg}":"..."}}}}',),
            description=reference_help[alias],
            executor="source",
            replay_class="safe",
        )
    from codey.research.tool_contract import question_bound_spec

    return {name: question_bound_spec(spec) for name, spec in specs.items()}


def _all_specs() -> dict[str, ToolSpec]:
    specs = _coding_specs()
    codemode_example = (
        "const result = await tools.read_file({path:inputs.path}); "
        "if (!result.ok) throw new Error(result.error); return result.value.text;"
    )
    codemode_inputs = {"path": "app.py"}
    data_example = {"code": "return inputs.text;", "inputs": {"text": "first\nsecond\n"}}
    specs["codemode"] = ToolSpec(
        name="codemode",
        grant="project.read",
        executor="codemode",
        replay_class="safe",
        description=(
            "Write an async JavaScript function body using tools.* and return its JSON result explicitly. "
            "Use return null for an intentional empty result. Normal authorization applies. "
            "Calls return {ok:true, value} or {ok:false, error}; check ok. "
            "For const result = await tools.NAME(...), use result.value.text for read_file "
            "and result.value.matches for grep (possibly an empty array). "
            "Await all tool/store/load calls. console.log/error fail; only return delivers data. "
            "No direct filesystem, process, network, shell or recursive CodeMode access. "
            f"{ARGUMENT_CONTENT_GUIDANCE} "
            "Put task data (paths, search queries, file contents) in inputs, not JS string literals. "
            "Read it as inputs.name; inputs is immutable JSON data, never executable source. "
            f"Example inputs={json.dumps(codemode_inputs)}; JavaScript: {codemode_example}\n"
            f"Multiline data arguments: {json.dumps(data_example)}"
        ),
        parameters=(
            ("code", {"type": "string"}),
            ("inputs", {"type": "object", "additionalProperties": True,
                        "description": "Named JSON data fields exposed as read-only inputs in JavaScript."}),
            ("language", {"type": "string", "enum": ["javascript", "js"]}),
        ),
        required=("code",),
        json_examples=(json.dumps({"tool": "codemode", "args": {"code": codemode_example,
                        "inputs": codemode_inputs}}, separators=(",", ":")),),
    )
    specs["ask_user"] = ToolSpec(
        name="ask_user", grant="control", replay_class="safe", executor="control",
        description="Ask a bounded choice question and pause for the user's answer. This authorizes no command. Must be the only call in the turn.",
        parameters=(("question", {"type": "string"}), ("options", {"type": "array", "items": {"type": "string"}}),
                    ("descriptions", {"type": "array", "items": {"type": "string"}}), ("allow_free_text", {"type": "boolean"})),
        required=("question", "options"),
        json_examples=('{"tool":"ask_user","args":{"question":"Which scope?","options":["Collect tests","Run tests"]}}',),
    )
    specs["read_tool_result"] = ToolSpec(
        name="read_tool_result", grant="control", executor="receipt", replay_class="safe",
        description="Read a stored result from this task without repeating its execution. "
                    "Use view=value for the full canonical JSON value, or view=output (default) for display/command output. "
                    "A missing canonical value is an error; display text cannot replace it. "
                    "Use query (a literal keyword, 1-512 characters) to locate a bounded excerpt in long output; "
                    "offset starts the search or selects a page. Not a regular expression.",
        parameters=(("result_ref", {"type": "string"}), ("view", {"type": "string", "enum": ["output", "value"]}),
                    ("offset", {"type": "integer", "minimum": 0}),
                    ("limit", {"type": "integer", "minimum": 1, "maximum": 8000}),
                    ("query", {"type": "string"})),
        required=("result_ref",),
        json_examples=('{"tool":"read_tool_result","args":{"result_ref":"...","query":"FAILED","limit":4000}}',),
    )
    for name, spec in _research_specs().items():
        if name == "done":
            # summary stays canonical; retain the research completion metadata.
            coding_done = specs.get("done")
            if coding_done is not None:
                specs["done"] = replace(coding_done, description=coding_done.description + " " + spec.description, parameters=(
                    *coding_done.parameters, ("open_questions", {"type": "array", "items": {"type": "string"}}),
                    ("knowledge_refs", {"type": "array", "items": {"type": "object", "required": ["id", "revision"],
                        "properties": {"id": {"type": "string"}, "revision": {"type": "integer", "minimum": 1}},
                        "additionalProperties": False}}),
                    ("report_sections", dict(spec.parameters)["report_sections"]),
                ))
            continue
        specs[name] = spec
    if "done" not in specs:
        specs["done"] = _coding_specs().get("done", ToolSpec(name="done", grant="control"))
    from codey.research.revision_tools import PREPARE, PREPARE_DESCRIPTION

    specs[PREPARE] = ToolSpec(
        name=PREPARE, grant="knowledge.write", executor="knowledge", replay_class="safe",
        description=PREPARE_DESCRIPTION,
        json_examples=('{"tool":"prepare_knowledge_revision","args":{}}',),
    )
    return specs


def _allowed_schema_keys(kind: str) -> set[str]:
    if kind in {"integer", "number"}:
        return {"type", "minimum", "maximum", "enum"}
    if kind == "string":
        return {"type", "enum", "minLength", "maxLength", "pattern"}
    if kind == "array":
        return {"type", "items", "enum", "minItems", "maxItems", "uniqueItems"}
    if kind == "object":
        return {"type", "properties", "required", "additionalProperties", "enum"}
    if kind == "boolean":
        return {"type", "enum"}
    return {"type"}


def _valid_schema_bounds(kind: str, schema: Mapping[Any, Any]) -> bool:
    for bound_key in ("minimum", "maximum"):
        if bound_key not in schema:
            continue
        if kind not in {"integer", "number"}:
            return False
        bound = schema[bound_key]
        if isinstance(bound, bool) or not isinstance(bound, (int, float)):
            return False
        try:
            import math as _math
            if isinstance(bound, float) and not _math.isfinite(bound):
                return False
        except Exception:
            return False
    if "minimum" in schema and "maximum" in schema:
        try:
            if float(schema["minimum"]) > float(schema["maximum"]):
                return False
        except Exception:
            return False
    return True


def _valid_schema_nested(kind: str, schema: Mapping[Any, Any]) -> bool:
    if kind == "array" and "items" in schema:
        return _valid_custom_schema(schema["items"])
    if kind != "object":
        return True
    props = schema.get("properties", {})
    if "properties" in schema:
        if not isinstance(props, dict):
            return False
        for _ps in props.values():
            if not _valid_custom_schema(_ps):
                return False
    if "required" in schema and not isinstance(schema["required"], list):
        return False
    extra = schema.get("additionalProperties", True)
    return isinstance(extra, bool) or _valid_custom_schema(extra)


def _valid_custom_schema(schema: object) -> bool:
    if not isinstance(schema, Mapping):
        return False
    kind = schema.get("type")
    if kind not in {"string", "integer", "number", "boolean", "object", "array"}:
        return False
    if any(key not in _allowed_schema_keys(str(kind)) for key in schema):
        return False
    if not _valid_schema_bounds(str(kind), schema):
        return False
    if "enum" in schema and not isinstance(schema["enum"], list):
        return False
    return _valid_schema_nested(str(kind), schema)


_SPECS: dict[str, ToolSpec] | None = None


def tool_specs() -> dict[str, ToolSpec]:
    global _SPECS
    if _SPECS is None:
        _SPECS = _all_specs()
    return _SPECS


def register_custom_tool(
    name: object,
    *,
    grant: object = "control",
    parameters: tuple[tuple[str, object], ...] = (),
    required: tuple[str, ...] = (),
    description: object = "",
    executor: object = "custom",
) -> bool:
    """Register a third-task tool without editing the kernel loop."""

    canonical = str(name or "").strip().lower()
    if not canonical or canonical in tool_specs():
        return False
    grant_text = str(grant or "").strip().lower()
    from codey.policies.capabilities import KNOWN_TASK_GRANTS

    if grant_text not in KNOWN_TASK_GRANTS:
        return False
    def valid_schema(schema: object) -> bool:
        return _valid_custom_schema(schema)
    for parameter_name, schema in parameters:
        if not (parameter_name or "").strip() or not valid_schema(schema):
            return False
    if any(not (item or "").strip() for item in required):
        return False
    example_args: dict[str, object] = {
        key: ([] if isinstance(schema, Mapping) and schema.get("type") == "array" else
                   {} if isinstance(schema, Mapping) and schema.get("type") == "object" else
                   0 if isinstance(schema, Mapping) and schema.get("type") in {"integer", "number"} else
                   False if isinstance(schema, Mapping) and schema.get("type") == "boolean" else "")
        for key, schema in parameters if key in set(required)
    }
    example = json.dumps({"tool": canonical, "args": example_args}, ensure_ascii=False)
    tool_specs()[canonical] = ToolSpec(
        name=canonical,
        aliases=(),
        grant=grant_text,
        parameters=tuple(parameters),
        required=tuple(required),
        json_examples=(example,),
        description=str(description or ""),
        executor=str(executor or "custom"),
        replay_class="unsafe",
    )
    return True


def canonical_tool_name(raw: object) -> str:
    name = str(raw or "").strip().lower()
    if not name:
        return ""
    specs = tool_specs()
    if name in specs:
        return name
    if name in _NATIVE_TO_CANONICAL:
        return _NATIVE_TO_CANONICAL[name]
    for spec in specs.values():
        if name in spec.aliases:
            return spec.name
    return ""


def spec_for_tool(name: object) -> ToolSpec | None:
    canonical = canonical_tool_name(name)
    if not canonical:
        return None
    return tool_specs().get(canonical)


def tool_requires_trusted_recovery(name: object) -> bool:
    """True when replay without verified provenance must fail closed.

    Unknown tools, empty names, registry errors, and any replay class other
    than ``safe`` all require trusted recovery. Safe reads (project reads,
    web/knowledge reads) may use the safe-replay path.
    """
    try:
        spec = spec_for_tool(name)
    except Exception:
        return True
    if spec is None:
        return True
    return str(getattr(spec, "replay_class", "unsafe") or "unsafe").strip().lower() != "safe"


def _policy_allows(policy: Any, grant: str) -> bool:
    allows = getattr(policy, "allows", None)
    if not callable(allows):
        return False
    try:
        return bool(allows(grant))
    except Exception:
        return False


def visible_tool_names(policy: Any) -> tuple[str, ...]:
    return visible_tool_names_for_snapshot(policy, None)


def _is_research_tool(name: str) -> bool:
    try:
        spec = tool_specs().get((name or "").strip().lower())
    except Exception:
        return False
    return spec is not None and spec.executor in {"source", "knowledge"}


def visible_tool_names_for_snapshot(policy: Any, controller_allowed: Any = None, *, native: bool = False) -> tuple[str, ...]:
    """Per-turn snapshot: policy ∩ current controller facts.

    The controller may only narrow research tools; it never removes project
    tools from a hybrid run. ``None`` means no controller narrowing.
    """
    allowed: set[str] | None = None
    if controller_allowed is not None:
        try:
            allowed = {str(n or "").strip().lower() for n in controller_allowed}
        except TypeError:
            allowed = None
    order = ("list_dir", "read_file", "read_files", "grep", "find_references", "parallel", "codemode", "edit", "run", "shell",
             "web_search", "open_url", "source_search", "knowledge_search", "knowledge_read",
             "research_plan", "save_finding", "save_inference", "knowledge_write", "knowledge_commit", "knowledge_link", "read_tool_result", "done")
    names: list[str] = []
    for name in order:
        if native and is_text_batch_tool(name):
            continue
        spec = tool_specs().get(name)
        if spec is None or not spec.grant:
            continue
        if not _policy_allows(policy, spec.grant):
            continue
        if allowed is not None and name != "done" and _is_research_tool(name) and name not in allowed:
            # Controller aliases lower to open_url; keep open_url visible when
            # any alias is allowed so the model can still reach the web.
            if name == "open_url" and bool({"open_url", "open_result", "reopen_source", "open_hit"} & allowed):
                pass
            else:
                continue
        names.append(name)
    # Controller aliases are model-visible names; expose them when allowed.
    for alias in ("open_result", "reopen_source", "open_hit"):
        spec = tool_specs().get(alias)
        if spec is None or alias in names:
            continue
        if _policy_allows(policy, spec.grant) and (allowed is None or alias in allowed):
            names.append(alias)
    # Registered third-task tools advertise alongside built-ins; unregistered
    # names stay denied.
    for name in sorted(tool_specs()):
        if name in names or name in order or name in {"open_result", "reopen_source", "open_hit"}:
            continue
        spec = tool_specs()[name]
        if spec.grant and _policy_allows(policy, spec.grant):
            if allowed is not None and _is_research_tool(name) and name not in allowed:
                continue
            names.append(name)
    return tuple(names)


def _schema_for_spec(spec: ToolSpec) -> dict[str, object]:
    properties: dict[str, object] = {}
    for param_name, schema in spec.parameters:
        properties[param_name] = dict(schema) if isinstance(schema, Mapping) else {"type": "string"}
    return {
        "type": "object",
        "properties": properties,
        "required": list(spec.required),
        "additionalProperties": False,
    }


def native_tools_for_policy(policy: Any) -> list[dict[str, object]]:
    return native_tools_for_snapshot(policy, None)


def native_tools_for_snapshot(policy: Any, controller_allowed: Any = None) -> list[dict[str, object]]:
    """Native schemas for one turn's snapshot; same source as JSON contract."""
    tools: list[dict[str, object]] = []
    for name in visible_tool_names_for_snapshot(policy, controller_allowed, native=True):
        spec = tool_specs().get(name)
        if spec is None:
            continue
        tools.append({
            "type": "function",
            "function": {
                "name": name,
                "description": model_tool_description(spec),
                "parameters": _schema_for_spec(spec),
            },
        })
    def tool_name(item: dict[str, object]) -> str:
        function = item.get("function")
        return str(function.get("name") or "") if isinstance(function, dict) else ""

    tools.sort(key=tool_name)
    return tools


def _spec_type_error(spec_name: str, key: str, want: str, got: object) -> str:
    try:
        got_name = type(got).__name__
    except Exception:
        got_name = "unknown"
    return f"{spec_name} arg '{key}' must be {want} (got {got_name})"


def _spec_want_and_bounds(schema: object) -> tuple[str, int | float | None, int | float | None]:
    want: str = ""
    minimum: int | float | None = None
    maximum: int | float | None = None
    try:
        if isinstance(schema, Mapping):
            want = str(schema.get("type", "") or "").strip().lower()
            if "minimum" in schema:
                raw_min = schema.get("minimum")
                if isinstance(raw_min, bool):
                    minimum = None
                elif isinstance(raw_min, (int, float)):
                    minimum = raw_min
            if "maximum" in schema:
                raw_max = schema.get("maximum")
                if isinstance(raw_max, bool):
                    maximum = None
                elif isinstance(raw_max, (int, float)):
                    maximum = raw_max
    except Exception:
        want, minimum, maximum = "", None, None
    return want, minimum, maximum


def _check_string_value(spec_name: str, key: str, value: Any) -> str:
    if not isinstance(value, str):
        return _spec_type_error(spec_name, key, "string", value)
    return ""


def _check_integer_value(
    spec_name: str, key: str, value: Any, minimum: int | float | None,
    maximum: int | float | None = None, *, strict: bool = False,
) -> str:
    if isinstance(value, bool):
        return _spec_type_error(spec_name, key, "integer", value)
    if isinstance(value, int):
        parsed = value
    elif isinstance(value, float):
        try:
            import math as _math

            if not _math.isfinite(value) or not float(value).is_integer():
                return _spec_type_error(spec_name, key, "integer", value)
            parsed = int(value)
        except Exception:
            return _spec_type_error(spec_name, key, "integer", value)
    elif isinstance(value, str):
        if strict:
            return _spec_type_error(spec_name, key, "integer", value)
        text = value.strip()
        if not text or not text.isascii():
            return _spec_type_error(spec_name, key, "integer", value)
        try:
            parsed = int(text)
        except ValueError:
            return _spec_type_error(spec_name, key, "integer", value)
    else:
        return _spec_type_error(spec_name, key, "integer", value)
    if minimum is not None:
        try:
            if parsed < minimum:
                return f"{spec_name} arg '{key}' must be >= {minimum}"
        except Exception:
            pass
    if maximum is not None:
        try:
            if parsed > maximum:
                return f"{spec_name} arg '{key}' must be <= {maximum}"
        except Exception:
            pass
    return ""


def _check_number_value(
    spec_name: str, key: str, value: Any, schema: object = None, *, strict: bool = False,
) -> str:
    import math

    _, minimum, maximum = _spec_want_and_bounds(schema)
    if isinstance(value, bool):
        return _spec_type_error(spec_name, key, "number", value)
    number = value
    if isinstance(value, str) and not strict:
        try:
            number = float(value.strip())
        except ValueError:
            return _spec_type_error(spec_name, key, "number", value)
    if not isinstance(number, (int, float)) or (isinstance(number, float) and not math.isfinite(number)):
        return _spec_type_error(spec_name, key, "number", value)
    if minimum is not None and number < minimum:
        return f"{spec_name} arg '{key}' must be >= {minimum}"
    if maximum is not None and number > maximum:
        return f"{spec_name} arg '{key}' must be <= {maximum}"
    return ""


def _check_boolean_value(spec_name: str, key: str, value: Any) -> str:
    if not isinstance(value, bool):
        return _spec_type_error(spec_name, key, "boolean", value)
    return ""


def _check_array_value(spec_name: str, key: str, schema: object, value: Any, *, strict: bool = False) -> str:
    if not isinstance(value, list):
        return _spec_type_error(spec_name, key, "array", value)
    if not isinstance(schema, Mapping) or schema.get("items") is None:
        return ""
    for bound_name, compare in (("minItems", len(value) < int(schema.get("minItems", 0))),
                           ("maxItems", len(value) > int(schema.get("maxItems", len(value))))):
        if compare:
            return f"{spec_name} arg '{key}' violates {bound_name}={schema[bound_name]}"
    if schema.get("uniqueItems") and any(value[i] == value[j] for i in range(len(value)) for j in range(i)):
        return f"{spec_name} arg '{key}' requires unique items"
    for index, item in enumerate(value):
        error = _check_spec_value_against_schema(spec_name, f"{key}[{index}]", schema["items"], item, strict=strict)
        if error:
            return error
    return ""


def _check_object_value(spec_name: str, key: str, schema: object, value: Any, *, strict: bool = False) -> str:
    if not isinstance(value, dict):
        return _spec_type_error(spec_name, key, "object", value)
    if isinstance(schema, Mapping):
        required = schema.get("required", ())
        if isinstance(required, (list, tuple)):
            for required_key in required:
                # 通用层严格按声明检查，不接受 edit 的历史别名。
                if required_key not in value:
                    return f"{spec_name} arg '{key}' missing required property '{required_key}'"
        properties = schema.get("properties", {})
        if isinstance(properties, Mapping):
            for child_key, child_value in value.items():
                canonical_child_key = str(child_key)
                child_schema = properties.get(canonical_child_key)
                if child_schema is None:
                    if schema.get("additionalProperties", True) is False:
                        return f"{spec_name} arg '{key}' unexpected property '{child_key}'"
                    child_schema = schema.get("additionalProperties")
                    if not isinstance(child_schema, Mapping):
                        continue
                error = _check_spec_value_against_schema(spec_name, f"{key}.{child_key}", child_schema, child_value, strict=strict)
                if error:
                    return error
    return ""


def _json_value_equal(left: Any, right: Any) -> bool:
    """JSON numbers compare numerically; booleans never compare as numbers."""
    if isinstance(left, bool) or isinstance(right, bool):
        return type(left) is type(right) and left == right
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return left == right
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(_json_value_equal(value, right[key]) for key, value in left.items())
    if isinstance(left, list):
        return len(left) == len(right) and all(_json_value_equal(a, b) for a, b in zip(left, right, strict=True))
    return cast(bool, left == right)


def _check_spec_value_against_schema(spec_name: str, key: str, schema: object, value: Any, *, strict: bool = False) -> str:
    """声明 schema 子集的类型检查（非 Full JSON-schema）。"""
    want, minimum, maximum = _spec_want_and_bounds(schema)
    if not want:
        return ""
    if isinstance(schema, Mapping) and "enum" in schema:
        enum = schema.get("enum")
        if isinstance(enum, (list, tuple)) and not any(_json_value_equal(value, item) for item in enum):
            return f"{spec_name} arg '{key}' must be one of {enum!r}"
    if want == "string":
        error = _check_string_value(spec_name, key, value)
        if error or not isinstance(schema, Mapping):
            return error
        if len(value) < int(schema.get("minLength", 0)) or len(value) > int(schema.get("maxLength", len(value))):
            return f"{spec_name} arg '{key}' violates declared string length bounds"
        if "pattern" in schema:
            import re

            if re.search(schema["pattern"], value) is None:
                return f"{spec_name} arg '{key}' must match {schema['pattern']}"
        return ""
    if want == "integer":
        return _check_integer_value(spec_name, key, value, minimum, maximum, strict=strict)
    if want == "number":
        return _check_number_value(spec_name, key, value, schema, strict=strict)
    if want == "boolean":
        return _check_boolean_value(spec_name, key, value)
    if want == "array":
        return _check_array_value(spec_name, key, schema, value, strict=strict)
    if want == "object":
        return _check_object_value(spec_name, key, schema, value, strict=strict)
    return ""


def _builtin_alias_allowed_keys(tool: str) -> set[str] | None:
    """Legacy alias sets for project tools; None means strict spec only."""
    name = (tool or "").strip().lower()
    if name in {"list_dir", "ls"}:
        return {"path", "cwd"}
    if name in {"read_file", "read"}:
        return {"path", "cwd", "offset", "limit"}
    if name in {"grep", "search"}:
        return {"query", "pattern", "path", "cwd", "offset", "limit", "literal", "case_sensitive",
                "include", "exclude", "before_context", "after_context"}
    if name in {"find_references", "references"}:
        return {"symbol", "name", "path", "cwd"}
    if name in {"run", "shell"}:
        return {"command", "cmd", "path", "cwd"}
    if name == "source_search":
        # Controller alias form: source_id + query without url.
        return {"url", "query", "limit", "source_id", "question_ref"}
    return None


def _builtin_required_satisfied(tool: str, required: tuple[str, ...], args: dict[str, Any]) -> str:
    """Alias-aware required check for built-ins; "" when satisfied else missing key."""
    name = (tool or "").strip().lower()
    # Groups where any member satisfies the canonical requirement.
    groups: dict[str, tuple[str, ...]] = {
        "path": ("path", "cwd"),
        "query": ("query", "pattern"),
        "symbol": ("symbol", "name"),
        "command": ("command", "cmd"),
    }
    # source_search special: source_id + query satisfies without url.
    if name == "source_search" and "source_id" in args:
        required = tuple(key for key in required if key != "url")
    for key in required:
        candidates = groups.get(key, (key,))
        found = False
        for cand in candidates:
            if cand in args:
                value = args.get(cand)
                if value is None:
                    continue
                # String required must be non-blank (after strip when str).
                if isinstance(value, str) and not value.strip():
                    continue
                found = True
                break
        if not found:
            return key
    return ""


def _declared_map(spec: Any) -> tuple[dict[str, object], str, bool]:
    declared: dict[str, object] = {}
    try:
        for param_name, schema in (spec.parameters or ()):
            declared[str(param_name)] = schema
    except Exception:
        declared = {}
    try:
        executor = str(getattr(spec, "executor", "") or "")
    except Exception:
        executor = ""
    return declared, executor, executor in {"project", "source", "knowledge"}


def _validate_required_presence(spec: Any, declared: dict[str, object], is_builtin: bool, args: dict[str, Any]) -> str:
    if is_builtin:
        missing_key = _builtin_required_satisfied(spec.name, tuple(spec.required or ()), args)
        if missing_key:
            return f"{spec.name} missing required arg '{missing_key}'"
        return ""
    for key in (spec.required or ()):
        if key not in args:
            return f"{spec.name} missing required arg '{key}'"
        value = args.get(key)
        if value is None:
            return f"{spec.name} missing required arg '{key}'"
        if isinstance(declared.get(key), Mapping):
            raw_declared = declared.get(key)
            want = str(raw_declared.get("type", "") or "").lower() if isinstance(raw_declared, Mapping) else ""
            if want == "string" and not str(value or "").strip():
                return f"{spec.name} missing required arg '{key}'"
    return ""


def validate_args_against_spec(name: object, args: object) -> str:
    """Single authoritative parameter check from the ToolSpec.

    Returns "" when args satisfy the ToolSpec (required presence, no extra
    args, JSON types); otherwise a short error. Project path/command/URL
    safety stays in the legacy validators, but shape is decided here so JSON
    and native prompts, schemas, and validation cannot drift.
    """
    spec = spec_for_tool(name)
    if spec is None:
        return f"unknown tool: {name or '?'}"
    return validate_args_with_spec(spec, args)


def _validate_no_extra(spec: Any, declared: dict[str, object], is_builtin: bool, args: dict[str, Any]) -> str:
    if is_builtin:
        allowed = _builtin_alias_allowed_keys(spec.name)
        if allowed is None:
            allowed = set(declared.keys())
        for key in args:
            if key not in allowed:
                return f"{spec.name} unexpected arg '{key}'"
        return ""
    for key in args:
        if key not in declared:
            return f"{spec.name} unexpected arg '{key}'"
    return ""


def _validate_types(spec: Any, declared: dict[str, object], is_builtin: bool, args: dict[str, Any]) -> str:
    if not is_builtin:
        for key, value in args.items():
            skey = key
            schema = declared.get(skey)
            if schema is None:
                continue
            error = _check_spec_value_against_schema(spec.name, skey, schema, value, strict=True)
            if error:
                return _parameter_error(error, schema)
        return ""
    _alias_to_canonical = {
        "cwd": "path", "pattern": "query", "name": "symbol", "cmd": "command",
        "source_id": "url",
    }
    for key, value in args.items():
        skey = key
        schema = declared.get(skey)
        if schema is None and is_builtin:
            canonical = _alias_to_canonical.get(skey)
            if canonical is not None:
                schema = declared.get(canonical)
            if schema is None:
                continue
        if schema is None:
            continue
        if skey == "source_id":
            if not isinstance(value, str) or not value.strip():
                return f"{spec.name} missing required arg 'source_id'"
            continue
        error = _check_spec_value_against_schema(spec.name, skey, schema, value)
        if error:
            return _parameter_error(error, schema)
    return ""


def _parameter_error(error: str, schema: object) -> str:
    description = schema.get("description", "") if isinstance(schema, Mapping) else ""
    return error + ". " + description if isinstance(description, str) and description else error


def validate_args_with_spec(spec: Any, args: object) -> str:
    """用给定冻结 spec 校验（快照本轮定义，不读 live 注册表）。"""
    if spec is None:
        return "unknown tool"
    if not isinstance(args, dict):
        return f"{getattr(spec, 'name', '?')} args must be an object"
    declared, _, is_builtin = _declared_map(spec)
    if "args" not in declared and isinstance(args.get("args"), dict):
        return (
            f"{spec.name} received an undeclared args wrapper. "
            "The tool name is already selected; pass its fields directly as arguments, not inside args. "
            f"Required top-level fields: {', '.join(spec.required) or '(none)'}. "
            f"Declared fields: {', '.join(declared)}. No tool was executed."
        )
    error = _validate_required_presence(spec, declared, is_builtin, args)
    if error:
        return error
    error = _validate_no_extra(spec, declared, is_builtin, args)
    if error:
        return error
    return _validate_types(spec, declared, is_builtin, args)


_CUSTOM_EXECUTORS: dict[str, Any] = {}


def register_custom_executor(name: object, fn: Any) -> bool:
    """Register a production executor for a third-task tool (generic path)."""
    canonical = str(name or "").strip().lower()
    if not canonical or not callable(fn):
        return False
    try:
        spec = spec_for_tool(canonical)
    except Exception:
        spec = None
    if spec is None:
        return False
    _CUSTOM_EXECUTORS[canonical] = fn
    return True


def custom_executor_for(name: object) -> Any | None:
    canonical = str(name or "").strip().lower()
    if not canonical:
        return None
    return _CUSTOM_EXECUTORS.get(canonical)


def unregister_custom_tool(name: object) -> bool:
    canonical = str(name or "").strip().lower()
    if not canonical:
        return False
    removed = False
    try:
        if canonical in tool_specs():
            # Never remove built-ins; only third-task registrations.
            builtin = _all_specs().get(canonical)
            if builtin is None:
                tool_specs().pop(canonical, None)
                removed = True
    except Exception:
        pass
    if canonical in _CUSTOM_EXECUTORS:
        _CUSTOM_EXECUTORS.pop(canonical, None)
        removed = True
    return removed


__all__ = [
    "ToolSpec",
    "canonical_tool_name",
    "custom_executor_for",
    "freeze_spec_parameters",
    "json_contract_text",
    "native_tools_for_policy",
    "native_tools_for_snapshot",
    "register_custom_executor",
    "register_custom_tool",
    "spec_for_tool",
    "tool_requires_trusted_recovery",
    "tool_specs",
    "unregister_custom_tool",
    "validate_args_against_spec",
    "validate_args_with_spec",
    "visible_tool_names",
    "visible_tool_names_for_snapshot",
]

